def countSameBstReorders(nums):
    MOD = 10 ** 9 + 7
    n = len(nums)
    left = [-1] * n
    right = [-1] * n
    for i in range(1, n):
        x = nums[i]
        u = 0
        while True:
            kids = left if x < nums[u] else right
            if kids[u] == -1:
                kids[u] = i
                break
            u = kids[u]
    size = [1] * n
    for u in range(n - 1, -1, -1):
        if left[u] != -1:
            size[u] += size[left[u]]
        if right[u] != -1:
            size[u] += size[right[u]]
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [pow(f, MOD - 2, MOD) for f in fact]
    ways = 1
    for u in range(n):
        a = size[left[u]] if left[u] != -1 else 0
        b = size[u] - 1 - a
        ways = ways * fact[a + b] % MOD * inv[a] % MOD * inv[b] % MOD
    return (ways - 1) % MOD
